begin;
do $$
declare a uuid;t uuid;p uuid;i uuid;j uuid;k uuid;req uuid:=gen_random_uuid();result jsonb;before_count integer;
begin
 select user_id into strict a from public.team_members where role='admin' limit 1;
 perform set_config('request.jwt.claim.sub',a::text,true);
 select id into strict t from public.tickets where available order by code limit 1;
 select count(*) into before_count from public.tickets;
 begin perform public.sell_numbered(gen_random_uuid(),t,'porta','Teste transacional','Pendente','');raise exception 'TEST: pendente aceito';exception when others then if SQLERRM like 'TEST:%' then raise;end if;end;
 perform public.sell_numbered(gen_random_uuid(),t,'porta','Teste transacional','Pix','');
 if not (select paid from public.tickets where id=t) then raise exception 'TEST: venda não paga';end if;
 perform public.claim_welcome_kit(t);perform public.claim_welcome_kit(t);
 if (select count(*) from public.benefit_claims where ticket_id=t)<>3 then raise exception 'TEST: kit duplicado';end if;
 insert into public.products(name,sector,price,requires_preparation)values('Teste SQL','cozinha',10,false)returning id into p;
 perform public.service_action(gen_random_uuid(),'order',jsonb_build_object('ticket_id',t,'product_id',p,'quantity',1));
 select id into strict i from public.items where ticket_id=t;
 if (select status from public.items where id=i)<>'pronto' then raise exception 'TEST: preparo indevido';end if;
 perform public.service_action(gen_random_uuid(),'order',jsonb_build_object('ticket_id',t,'product_id',p,'quantity',2));
 select id into strict j from public.items where ticket_id=t and id<>i;
 perform public.settle_items(req,t,array[i],'Dinheiro',false,10);
 perform public.settle_items(req,t,array[i],'Dinheiro',false,10);
 if (select count(*) from public.payments where ticket_id=t)<>1 or (select closed from public.tickets where id=t) then raise exception 'TEST: duplicou ou encerrou';end if;
 begin perform public.settle_items(gen_random_uuid(),t,array[i],'Pix',false,10);raise exception 'TEST: cobrou item pago';exception when others then if SQLERRM like 'TEST:%' then raise;end if;end;
 begin perform public.service_action(gen_random_uuid(),'status',jsonb_build_object('ticket_id',t,'item_id',i,'status','cancelado','reason','teste'));raise exception 'TEST: cancelou pago';exception when others then if SQLERRM like 'TEST:%' then raise;end if;end;
 perform public.service_action(gen_random_uuid(),'status',jsonb_build_object('ticket_id',t,'item_id',j,'status','cancelado','reason','teste'));
 perform public.service_action(gen_random_uuid(),'order',jsonb_build_object('ticket_id',t,'product_id',p,'quantity',2));
 select id into strict k from public.items where ticket_id=t and id not in (i,j);
 begin perform public.settle_items(gen_random_uuid(),t,array[k],'Pix',false,1);raise exception 'TEST: valor adulterado';exception when others then if SQLERRM like 'TEST:%' then raise;end if;end;
 update public.team_members set role='cozinha' where user_id=a;
 begin perform public.settle_items(gen_random_uuid(),t,array[k],'Pix',false,20);raise exception 'TEST: cozinha recebeu';exception when others then if SQLERRM like 'TEST:%' then raise;end if;end;
 update public.team_members set role='admin' where user_id=a;
 perform public.settle_items(gen_random_uuid(),t,'{}','Cartão',true,20);
 if not (select closed from public.tickets where id=t) or (select sum(amount) from public.payments where ticket_id=t)<>30 then raise exception 'TEST: fechamento errado';end if;
 perform public.service_action(gen_random_uuid(),'status',jsonb_build_object('ticket_id',t,'item_id',k,'status','entregue'));
 if (select count(*) from public.items where ticket_id=t)<>3 then raise exception 'TEST: perdeu histórico';end if;
 if (select count(*) from public.tickets)<>before_count then raise exception 'TEST: alterou inventário';end if;
end $$;
rollback;
select 'Testes aprovados: venda, kit, preparo, pagamento parcial, repetição, autorização, cancelamento, encerramento e histórico. Nenhum dado de teste persistido.' as resultado;
